GRANT EXECUTE ON FUNCTION public.pm_project_b1_active() TO postgres;
CREATE FUNCTION public.pm_b1_review_redaction(_row jsonb,_project uuid,_user uuid,_kind text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF _user IS NULL THEN RAISE EXCEPTION 'Explicit review identity required'; END IF; PERFORM set_config('request.jwt.claim.sub',_user::text,true); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',_user,'role','authenticated')::text,true); result:=public.pm_b1_redact(_row,_project,_kind); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.pm_b1_review_redaction(jsonb,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION public.pm_b1_review_redaction(jsonb,uuid,uuid,text) IS 'Not client callable; reserved isolated transaction verification helper. No gate activation or data mutation.';